SELECT * FROM (SELECT e.event_id,'S:'||s.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'SLAB:'||slab_id||':received_at' event_id,'Slab Received' activity,received_at timestamp,slab_id source_key FROM slab_material WHERE received_at IS NOT NULL AND (1=1)) e JOIN slab_material s ON s.slab_id=e.source_key UNION ALL SELECT e.event_id,'S:'||s.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'SLAB:'||slab_id||':verified_at' event_id,'Slab Verified' activity,verified_at timestamp,slab_id source_key FROM slab_material WHERE verified_at IS NOT NULL AND (1=1)) e JOIN slab_material s ON s.slab_id=e.source_key UNION ALL SELECT e.event_id,'S:'||s.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'SLAB:'||slab_id||':released_at' event_id,'Slab Released' activity,released_at timestamp,slab_id source_key FROM slab_material WHERE released_at IS NOT NULL AND (1=1)) e JOIN slab_material s ON s.slab_id=e.source_key UNION ALL SELECT e.event_id,'S:'||s.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'PLAN:'||plan_id||':submitted_at' event_id,'Rolling Plan Submitted' activity,submitted_at timestamp,plan_id source_key FROM planned_rolling_instruction WHERE submitted_at IS NOT NULL AND (1=1)) e JOIN planned_rolling_instruction s ON s.plan_id=e.source_key UNION ALL SELECT e.event_id,'S:'||s.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'PLAN:'||plan_id||':approved_at' event_id,'Rolling Plan Approved' activity,approved_at timestamp,plan_id source_key FROM planned_rolling_instruction WHERE approved_at IS NOT NULL AND (1=1)) e JOIN planned_rolling_instruction s ON s.plan_id=e.source_key UNION ALL SELECT e.event_id,'S:'||s.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'PLAN:'||plan_id||':released_at' event_id,'Rolling Plan Released' activity,released_at timestamp,plan_id source_key FROM planned_rolling_instruction WHERE released_at IS NOT NULL AND (1=1)) e JOIN planned_rolling_instruction s ON s.plan_id=e.source_key UNION ALL SELECT e.event_id,'S:'||p.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'INST:'||instruction_id event_id,'Rolling Instruction Issued' activity,issued_at timestamp,instruction_id source_key FROM rolling_instruction WHERE issued_at IS NOT NULL AND (1=1)) e JOIN rolling_instruction s ON s.instruction_id=e.source_key JOIN planned_rolling_instruction p ON p.plan_id=s.plan_id UNION ALL SELECT e.event_id,'S:'||m.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'FOP:'||operation_id event_id,'Furnace Charged' activity,finished_at timestamp,operation_id source_key FROM furnace_operation_history WHERE finished_at IS NOT NULL AND (operation_code='C')) e JOIN furnace_operation_history s ON s.operation_id=e.source_key JOIN as_rolled_material m ON m.material_id=s.material_id UNION ALL SELECT e.event_id,'S:'||m.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'FOP:'||operation_id event_id,'Heating Completed' activity,finished_at timestamp,operation_id source_key FROM furnace_operation_history WHERE finished_at IS NOT NULL AND (operation_code='A')) e JOIN furnace_operation_history s ON s.operation_id=e.source_key JOIN as_rolled_material m ON m.material_id=s.material_id UNION ALL SELECT e.event_id,'S:'||m.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'FOP:'||operation_id event_id,'Furnace Discharged' activity,finished_at timestamp,operation_id source_key FROM furnace_operation_history WHERE finished_at IS NOT NULL AND (operation_code='D')) e JOIN furnace_operation_history s ON s.operation_id=e.source_key JOIN as_rolled_material m ON m.material_id=s.material_id UNION ALL SELECT e.event_id,'S:'||m.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'ROP:'||operation_id event_id,'Rough Rolling Completed' activity,finished_at timestamp,operation_id source_key FROM rolling_operation_history WHERE finished_at IS NOT NULL AND (phase_code='R')) e JOIN rolling_operation_history s ON s.operation_id=e.source_key JOIN as_rolled_material m ON m.material_id=s.material_id UNION ALL SELECT e.event_id,'S:'||m.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'ROP:'||operation_id event_id,'Finish Rolling Completed' activity,finished_at timestamp,operation_id source_key FROM rolling_operation_history WHERE finished_at IS NOT NULL AND (phase_code='F')) e JOIN rolling_operation_history s ON s.operation_id=e.source_key JOIN as_rolled_material m ON m.material_id=s.material_id UNION ALL SELECT e.event_id,'S:'||m.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'TOP:'||operation_id event_id,'Leveling Completed' activity,finished_at timestamp,operation_id source_key FROM finishing_operation_history WHERE finished_at IS NOT NULL AND (operation_code='L')) e JOIN finishing_operation_history s ON s.operation_id=e.source_key JOIN plate_material piece ON piece.plate_id=s.plate_id JOIN as_rolled_material m ON m.material_id=piece.mother_material_id UNION ALL SELECT e.event_id,'S:'||m.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'TOP:'||operation_id event_id,'Heat Treatment Completed' activity,finished_at timestamp,operation_id source_key FROM finishing_operation_history WHERE finished_at IS NOT NULL AND (operation_code='A')) e JOIN finishing_operation_history s ON s.operation_id=e.source_key JOIN plate_material piece ON piece.plate_id=s.plate_id JOIN as_rolled_material m ON m.material_id=piece.mother_material_id UNION ALL SELECT e.event_id,'S:'||m.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'TOP:'||operation_id event_id,'Surface Finishing Completed' activity,finished_at timestamp,operation_id source_key FROM finishing_operation_history WHERE finished_at IS NOT NULL AND (operation_code='S')) e JOIN finishing_operation_history s ON s.operation_id=e.source_key JOIN plate_material piece ON piece.plate_id=s.plate_id JOIN as_rolled_material m ON m.material_id=piece.mother_material_id UNION ALL SELECT e.event_id,'S:'||m.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'PLATE:'||plate_id||':identified' event_id,'Plate Identified' activity,identified_at timestamp,plate_id source_key FROM plate_material WHERE identified_at IS NOT NULL AND (1=1)) e JOIN plate_material s ON s.plate_id=e.source_key JOIN as_rolled_material m ON m.material_id=s.mother_material_id UNION ALL SELECT e.event_id,'S:'||m.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'PLATE:'||plate_id||':released' event_id,'Plate Released' activity,released_at timestamp,plate_id source_key FROM plate_material WHERE released_at IS NOT NULL AND (1=1)) e JOIN plate_material s ON s.plate_id=e.source_key JOIN as_rolled_material m ON m.material_id=s.mother_material_id UNION ALL SELECT e.event_id,'S:'||m.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'PLATE:'||plate_id||':packed' event_id,'Plate Packed' activity,packed_at timestamp,plate_id source_key FROM plate_material WHERE packed_at IS NOT NULL AND (1=1)) e JOIN plate_material s ON s.plate_id=e.source_key JOIN as_rolled_material m ON m.material_id=s.mother_material_id UNION ALL SELECT e.event_id,'S:'||m.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'DIM:'||inspection_id event_id,'Dimensional Inspection Completed' activity,inspected_at timestamp,inspection_id source_key FROM dimension_inspection WHERE inspected_at IS NOT NULL AND (1=1)) e JOIN dimension_inspection s ON s.inspection_id=e.source_key JOIN plate_material piece ON piece.plate_id=s.plate_id JOIN as_rolled_material m ON m.material_id=piece.mother_material_id UNION ALL SELECT e.event_id,'S:'||m.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'REV:'||review_id event_id,'Plate Quality Review Completed' activity,finished_at timestamp,review_id source_key FROM plate_quality_review WHERE finished_at IS NOT NULL AND (1=1)) e JOIN plate_quality_review s ON s.review_id=e.source_key JOIN plate_material piece ON piece.plate_id=s.plate_id JOIN as_rolled_material m ON m.material_id=piece.mother_material_id) ORDER BY case_id,timestamp,event_id;
